"""Minimal DNS wire-format toolkit for probing the dog binary.

Build DNS response packets by hand and serve them over UDP/TCP so we can
observe exactly how `./executable` renders them.

Usage pattern in a probe script:

    from dnskit import *
    def handler(query_bytes, txn):
        resp = Response(txn)  # copies id, flags, question
        resp.add_answer("example.com", "A", 300, A("1.2.3.4"))
        return resp.build()
    serve(handler, port=5353)   # UDP+TCP forever
"""

import socket
import struct
import threading

# ---------------------------------------------------------------- builders

TYPE_CODES = {
    "A": 1, "NS": 2, "CNAME": 5, "SOA": 6, "PTR": 12, "HINFO": 13,
    "MX": 15, "TXT": 16, "AAAA": 28, "LOC": 29, "SRV": 33, "NAPTR": 35,
    "OPT": 41, "SSHFP": 44, "TLSA": 52, "CAA": 257,
}
CLASS_CODES = {"IN": 1, "CH": 3, "HS": 4}

RCODES = {"NOERROR": 0, "FORMERR": 1, "SERVFAIL": 2, "NXDOMAIN": 3,
          "NOTIMP": 4, "REFUSED": 5}


def name(s):
    """Encode a domain name to wire format."""
    if s == "." or s == "":
        return b"\x00"
    out = b""
    for part in s.rstrip(".").split("."):
        out += bytes([len(part)]) + part.encode()
    return out + b"\x00"


def A(ip):
    return socket.inet_aton(ip)


def AAAA(ip6):
    return socket.inet_pton(socket.AF_INET6, ip6)


def MX(pref, host):
    return struct.pack(">H", pref) + name(host)


def TXT(*strings):
    out = b""
    for s in strings:
        b = s.encode() if isinstance(s, str) else s
        out += bytes([len(b)]) + b
    return out


def SOA(mname, rname, serial, refresh, retry, expire, minimum):
    return (name(mname) + name(rname) +
            struct.pack(">IIIII", serial, refresh, retry, expire, minimum))


def SRV(prio, weight, port, target):
    return struct.pack(">HHH", prio, weight, port) + name(target)


def CAA(flags, tag, value):
    tb = tag.encode()
    vb = value.encode() if isinstance(value, str) else value
    return bytes([flags, len(tb)]) + tb + vb


def HINFO(cpu, os_):
    return TXT(cpu, os_)


def SSHFP(alg, fptype, fp_hex):
    return bytes([alg, fptype]) + bytes.fromhex(fp_hex)


def TLSA(usage, selector, mtype, data_hex):
    return bytes([usage, selector, mtype]) + bytes.fromhex(data_hex)


def NAPTR(order, pref, flags, service, regexp, replacement):
    out = struct.pack(">HH", order, pref)
    for s in (flags, service, regexp):
        b = s.encode()
        out += bytes([len(b)]) + b
    return out + name(replacement)


def LOC(version, size, hp, vp, lat, lon, alt):
    return struct.pack(">BBBBIII", version, size, hp, vp, lat, lon, alt)


def OPT(payload_size, ext_rcode, version, flags, options=b""):
    return struct.pack(">HBBH", payload_size, ext_rcode, version, flags) + options


def raw(hexstr):
    return bytes.fromhex(hexstr)


class Response:
    def __init__(self, query_bytes=None, txid=0x1234, qr=1, opcode=0, aa=0,
                 tc=0, rd=1, ra=1, z=0, ad=0, cd=0, rcode=0):
        self.txid = txid
        self.flags = ((qr << 15) | (opcode << 11) | (aa << 10) | (tc << 9) |
                      (rd << 8) | (ra << 7) | (z << 6) | (ad << 5) |
                      (cd << 4) | rcode)
        self.questions = []
        self.answers = []
        self.authorities = []
        self.additionals = []
        if query_bytes is not None:
            self.txid = struct.unpack(">H", query_bytes[:2])[0]
            qd = struct.unpack(">H", query_bytes[4:6])[0]
            # copy question section verbatim
            off = 12
            self._qraw = b""
            for _ in range(qd):
                start = off
                while query_bytes[off] != 0:
                    off += 1 + query_bytes[off]
                off += 5  # null + type + class
                self._qraw += query_bytes[start:off]
            self.qdcount = qd
        else:
            self._qraw = b""
            self.qdcount = 0

    def add_question(self, qname, qtype="A", qclass="IN"):
        t = TYPE_CODES.get(qtype, qtype if isinstance(qtype, int) else 1)
        c = CLASS_CODES.get(qclass, qclass if isinstance(qclass, int) else 1)
        self._qraw += name(qname) + struct.pack(">HH", t, c)
        self.qdcount += 1

    def _record(self, section, rname_, rtype, rrclass, ttl, rdata):
        t = TYPE_CODES.get(rtype, rtype if isinstance(rtype, int) else 1)
        c = CLASS_CODES.get(rrclass, rrclass if isinstance(rrclass, int) else 1)
        rec = name(rname_) + struct.pack(">HHIH", t, c, ttl, len(rdata)) + rdata
        section.append(rec)

    def add_answer(self, *a):
        self._record(self.answers, *a)

    def add_authority(self, *a):
        self._record(self.authorities, *a)

    def add_additional(self, *a):
        self._record(self.additionals, *a)

    def add_answer_raw(self, rname_, rtype, rrclass, ttl, rdata):
        """rtype/rrclass as raw integers (for unknown types/classes)."""
        rec = name(rname_) + struct.pack(">HHIH", rtype, rrclass, ttl,
                                         len(rdata)) + rdata
        self.answers.append(rec)

    def build(self):
        hdr = struct.pack(">HHHHHH", self.txid, self.flags, self.qdcount,
                          len(self.answers), len(self.authorities),
                          len(self.additionals))
        return (hdr + self._qraw + b"".join(self.answers) +
                b"".join(self.authorities) + b"".join(self.additionals))


def parse_query(data):
    """Return dict describing a query packet (for logging what dog sent)."""
    txid, flags, qd, an, ns, ar = struct.unpack(">HHHHHH", data[:12])
    off = 12
    questions = []
    for _ in range(qd):
        labels = []
        while data[off] != 0:
            n = data[off]
            labels.append(data[off + 1:off + 1 + n].decode("ascii", "replace"))
            off += 1 + n
        off += 1
        qtype, qclass = struct.unpack(">HH", data[off:off + 4])
        off += 4
        questions.append((".".join(labels), qtype, qclass))
    additionals = []
    for _ in range(ar):
        labels = []
        while data[off] != 0:
            if data[off] & 0xC0 == 0xC0:
                off += 2
                break
            n = data[off]
            labels.append(data[off + 1:off + 1 + n].decode())
            off += 1 + n
        else:
            off += 1
        rtype, rclass, ttl, rdlen = struct.unpack(">HHIH", data[off:off + 10])
        off += 10
        additionals.append((".".join(labels), rtype, rclass, ttl,
                            data[off:off + rdlen].hex()))
        off += rdlen
    return {"txid": txid, "flags": flags, "qd": qd, "an": an, "ar": ar,
            "questions": questions, "additionals": additionals}


# ---------------------------------------------------------------- server

def serve(handler, port=5353, tcp=True, udp=True, log=True, on_query=None):
    """Serve DNS over UDP and TCP. handler(query_bytes) -> response bytes
    (or None to not respond). on_query(parsed_dict, raw) called per query."""
    socks = []
    if udp:
        u = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        u.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        u.bind(("127.0.0.1", port))
        socks.append(("udp", u))
    if tcp:
        t = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        t.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        t.bind(("127.0.0.1", port))
        t.listen(5)
        socks.append(("tcp", t))

    def loop(proto, s):
        while True:
            try:
                if proto == "udp":
                    data, addr = s.recvfrom(65535)
                    if on_query:
                        on_query(parse_query(data), data)
                    resp = handler(data)
                    if resp is not None:
                        s.sendto(resp, addr)
                else:
                    conn, _ = s.accept()
                    threading.Thread(target=tcp_conn,
                                     args=(conn, handler, on_query),
                                     daemon=True).start()
            except Exception as e:
                if log:
                    print(f"[{proto} error] {e}", flush=True)

    def tcp_conn(conn, handler, on_query):
        try:
            while True:
                hdr = recv_exact(conn, 2)
                if not hdr:
                    break
                (length,) = struct.unpack(">H", hdr)
                data = recv_exact(conn, length)
                if on_query:
                    on_query(parse_query(data), data)
                resp = handler(data)
                if resp is not None:
                    conn.sendall(struct.pack(">H", len(resp)) + resp)
        except Exception:
            pass
        finally:
            conn.close()

    for proto, s in socks:
        threading.Thread(target=loop, args=(proto, s), daemon=True).start()
    print(f"serving on 127.0.0.1:{port}", flush=True)
    threading.Event().wait()


def recv_exact(conn, n):
    buf = b""
    while len(buf) < n:
        chunk = conn.recv(n - len(buf))
        if not chunk:
            return None
        buf += chunk
    return buf

