#!/usr/bin/env python3
"""Misc probe: NXDOMAIN, full sections, unknown type."""
import sys
sys.path.insert(0, "/workspace/probe")
from dnskit import *

mode = sys.argv[2] if len(sys.argv) > 2 else "nxdomain"

def handler(q):
    if mode == "nxdomain":
        return Response(q, rcode=3, aa=1)
    if mode == "full":
        r = Response(q, aa=1)
        r.add_answer("example.com", "A", 300, A("1.2.3.4"))
        r.add_authority("example.com", "NS", 3600, name("ns1.example.com"))
        r.add_additional("ns1.example.com", "A", 3600, A("5.6.7.8"))
        return r
    if mode == "unknown":
        r = Response(q)
        r.add_answer_raw("example.com", 99, 1, 60, b"\x01\x02\x03\x04")
        return r
    if mode == "multi":
        r = Response(q)
        r.add_answer("example.com", "A", 300, A("1.2.3.4"))
        r.add_answer("example.com", "A", 300, A("5.6.7.8"))
        return r

if __name__ == "__main__":
    serve(handler, port=int(sys.argv[1]))
